export type QuoteStep = {
  op: "quote";
  items: { type: string }[];
};

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
};

export type ScenarioResult = {
  results: unknown[];
};

const PROCESSING_FEE = 5;
const SWORD_PREMIUM_WITH_FIRST_INSURANCE = 110;

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const results = scenario.steps.map((step) => {
    if (step.items.length === 0) return { premium: PROCESSING_FEE };
    return { premium: SWORD_PREMIUM_WITH_FIRST_INSURANCE + PROCESSING_FEE };
  });

  return { results };
};
=====TEST=====
import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Simplest case ---
  it("should charge only the processing fee for an empty item list — premium 5 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(result).toEqual({ results: [{ premium: 5 }] });
  });

  // --- Base premiums per main item type ---
  it("should quote a plain sword — premium 115 G (100 base + 10 first insurance + 5 fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "sword", material: "steel", enchantment: 3, cursed: false },
          ],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it.todo("should quote a plain amulet — premium 71 G (60 base + 6 first insurance + 5 fee)");
  it.todo("should quote a plain staff — premium 93 G (80 base + 8 first insurance + 5 fee)");
  it.todo("should quote a plain potion — premium 49 G (40 base + 4 first insurance + 5 fee)");

  // --- Component base premiums and the block of 3 alike ---
  it.todo("should quote a single rune — base premium 25 G");
  it.todo("should quote a single moonstone — base premium 25 G");
  it.todo("should quote 2 runes — base premium 50 G (no block)");
  it.todo("should quote 3 runes — base premium 60 G (block applies)");
  it.todo("should quote 4 runes — base premium 100 G (no block — block requires exactly 3)");
  it.todo("should quote 7 runes — base premium 175 G");
  it.todo("should quote 2 runes + 1 moonstone — base premium 75 G (no block: different types)");
  it.todo("should quote 3 runes + 3 moonstones — base premium 120 G (two separate blocks)");

  // --- Item-specific modifiers ---
  it.todo("should add a 50% curse surcharge to the cursed item's base premium — cursed sword base 150 G");
  it.todo("should add a 30% high-enchantment surcharge at enchantment 5 — sword base 130 G");
  it.todo("should not add the high-enchantment surcharge at enchantment 4 — sword base 100 G");
  it.todo("should apply both surcharges to a cursed sword with enchantment 5 — base 180 G");

  // --- Policy-wide modifiers ---
  it.todo("should apply the 20% loyalty discount at exactly 2 years with MHPCO");
  it.todo("should not apply the loyalty discount at 1 year with MHPCO");
  it.todo("should apply the 10% first insurance surcharge to every item in a quote");
  it.todo("should apply the 15% follow-up discount on each contract after the first");
  it.todo("should add the 5 G processing fee at the very end of every premium");

  // --- Modifier scope on multi-item policies ---
  it.todo("should apply the curse surcharge only to the cursed item — cursed sword + plain amulet: 160 G base + 50 G curse = 210 G before further modifiers and fee");

  // --- Rounding ---
  it.todo("should round a premium of 197.5 G up to 198 G (in MHPCO's favor)");
  it.todo("should round a payout of 350.5 G down to 350 G (in MHPCO's favor)");
  it.todo("should keep intermediate amounts as fractions and round only the final amount");

  // --- Integration examples ---
  it.todo("should quote a newcomer's cursed sword (0 years, steel, enchantment 3) — premium 165 G");
  it.todo("should quote a long-standing customer's second contract (3 years, cursed sword, enchantment 7) — premium 160 G");

  // --- Insurance sums and caps ---
  it.todo("should compute insurance sum 1600 G and cap 3200 G for a policy covering a sword and an amulet");
  it.todo("should compute insurance sum 2000 G and cap 4000 G for a policy covering two swords");
  it.todo("should compute insurance sum 1750 G for a sword and 3 runes — the block discount affects the premium only");
  it.todo("should base the cap on the unmodified insurance value — cursed sword (premium 165 G) still has cap 2000 G");

  // --- Standard reimbursement ---
  it.todo("should reimburse a regular sword (steel, enchantment 3) damaged 500 G — payout 400 G");
  it.todo("should reimburse a damaged rune (damage 200 G) — payout 100 G (no enchantment or material, no special clause)");

  // --- Special clauses ---
  it.todo("should reimburse damage to an item with enchantment >= 8 at 50% — dragon sword, enchantment 8, damage 1000 G → payout 400 G");
  it.todo("should fully reimburse dragon-material damage — dragon sword, enchantment 5, damage 800 G → payout 700 G");
  it.todo("should let the 50% rule win when both clauses apply — dragon sword, enchantment 9, damage 1000 G → payout 400 G");
  it.todo("should apply only the high-enchantment clause to a steel sword, enchantment 9, damage 1000 G → payout 400 G");

  // --- Deductible per damage event ---
  it.todo("should apply the 100 G deductible once per damaged item — sword 500 G + amulet 300 G → payout 600 G");
  it.todo("should treat two damage entries of the same type as separate damages with their own deductible");

  // --- Cap exhaustion ---
  it.todo("should report the remaining cap after a claim — sword (cap 2000 G), claim 1500 G → payout 1400 G, remainingCap 600 G");
  it.todo("should reduce a payout to the remaining cap — second claim of 1500 G → payout 600 G, remainingCap 0 G");

  // --- Error cases ---
  it.todo("should reject a quote containing an item with an unknown type (e.g. broomstick)");
  it.todo("should reject a claim whose damage references an item not part of the policy (amulet damaged, only a sword insured)");
  it.todo("should reject a claim whose damage references an item with an unknown type");
  it.todo("should reject a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured)");
  it.todo("should reject a claim containing a damage entry with a negative amount (-200)");

  // --- Scenario / CLI end-to-end ---
  it.todo("should return one result per step, in the order of the input steps");
  it.todo("should let a claim step reference the policy created by an earlier quote step via its zero-based index");
  it.todo("should process the schema example scenario (5 years, amulet quote then a 200 G fire claim)");
  it.todo("CLI should read a scenario from stdin and write {results: [...]} to stdout");
  it.todo("CLI should exit with a non-zero status and write an error to stderr for an invalid scenario, writing no results to stdout");
});

export type QuoteStep = {
  op: "quote";
  items: { type: string }[];
};

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
};

export type ScenarioResult = {
  results: unknown[];
};

const PROCESSING_FEE = 5;
// The only non-empty item list any active test covers is a single plain sword,
// whose premium including the first-insurance surcharge is 110 G. The base and
// the surcharge stay folded together until a test distinguishes them.
const PREMIUM_FOR_ANY_NON_EMPTY_ITEM_LIST = 110;

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const results = scenario.steps.map((step) => {
    if (step.items.length === 0) return { premium: PROCESSING_FEE };
    return { premium: PREMIUM_FOR_ANY_NON_EMPTY_ITEM_LIST + PROCESSING_FEE };
  });

  return { results };
};

